2_1.code_example:
CREATE TABLE clubes_demo (
  id INTEGER PRIMARY KEY
);

CREATE TABLE actividades_demo (
  id INTEGER PRIMARY KEY,
  nombre TEXT NOT NULL,
  costo REAL
);

CREATE TABLE notas_demo (
  id INTEGER PRIMARY KEY,
  nota REAL NOT NULL
    CHECK(nota BETWEEN 1 AND 7)
);

