3_1.code_example:
SELECT id, asistencia
FROM tutorias
ORDER BY id;

SELECT COUNT(*) AS filas,
  COUNT(asistencia) AS conocidas
FROM tutorias;

SELECT SUM(asistencia), AVG(asistencia),
  MIN(asistencia), MAX(asistencia)
FROM tutorias;

3_2.code_example:
SELECT nombre, creditos
FROM materias
ORDER BY creditos, nombre;

3_4.code_example:
SELECT id, estudiante_id, tema
FROM tutorias
ORDER BY id;

4_1.code_example:
SELECT estudiante_id
FROM tutorias
WHERE asistencia = 1;

SELECT nombre
FROM estudiantes
WHERE id IN (
  SELECT estudiante_id FROM tutorias
  WHERE asistencia = 1
);

SELECT id, tema, asistencia
FROM tutorias
WHERE asistencia IS NULL;

SELECT nombre, semestre
FROM estudiantes
WHERE id NOT IN (
  SELECT estudiante_id FROM tutorias
  WHERE estudiante_id IS NOT NULL
);

4_3.code_example:
